#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)] // test code: helpers panic on purpose
//! Oracle tests for the dataset (T-148, specs/data.md OD-01 to OD-05).
//!
//! The files are `oracle/data/*.csv` and `oracle/data/population/*.csv`; what must come out of each is
//! in `oracle/expected/data/<case>.json`, written by `oracle/scripts/data_population.R` (the data
//! facts are computed in R from the file, with `nlme::groupedData` as a cross-check; the sentences are
//! hand-written from the definitions). The list of cases is `oracle_data.cases`, generated by the
//! same script; a guard compares it with what is on disk.
//!
//! This file uses only `std` and `serde_json` (the project crate has no dev-dependencies).
//!
//! What is red on purpose (until T-150 lands):
//! - the `records` test of every load case (the reading has no `dataset` yet);
//! - the `table` test of the event-layout files (the roles `event`, `cmt`, `mdv`, `cens`, `limit`,
//!   `rate`, `dur` and `covariate` do not exist yet) and of the cases that declare covariates;
//! - the `refused` test of every refusal except `time_not_increasing`, which is today's check;
//! - the parity of the profile and event layouts of Theoph and Indometh.
//!
//! What is green today and must stay green: the guards, the `table` test of every profile-layout
//! file, and `legacy_files_load_as_pinned` (OD-03: the notes, the checks and the number of readings
//! of today's importer, pinned in `oracle/expected/data/legacy_notes.json`).
//!
//! The API assumed, in one place (`dataset_of` and `options_of`): a `Reading` serialized to JSON
//! has, beside `table` and `checks`, a `dataset` object
//! `{ layout, subjects: [ { id, n_rows, doses: [ { row, time, amount, rate, duration, kind } ],
//! observations: [ { row, time, status, value } ], n_obs, n_observed, n_missing, n_blq,
//! covariates: { name: value } } ] }`, with rows counted from 1 over the data rows, `status` one of
//! `observed`, `missing`, `blq`, and `kind` one of `bolus`, `infusion`; `CsvOptions` has a
//! `covariates` list of column names; a refused table is a reading whose `checks` hold the code and
//! the sentence (the spec: "checks are readings checks").

use caladrius_project::{CsvOptions, readings};
use serde_json::Value;
use std::path::{Path, PathBuf};

const RELATIVE: f64 = 1e-12;

fn oracle() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../oracle")
}

fn read_json(path: &Path) -> Value {
    let text = std::fs::read_to_string(path)
        .unwrap_or_else(|e| panic!("cannot read {}: {e}", path.display()));
    serde_json::from_str(&text).unwrap_or_else(|e| panic!("{} is not JSON: {e}", path.display()))
}

fn expected(case: &str) -> Value {
    read_json(&oracle().join("expected/data").join(format!("{case}.json")))
}

fn bytes_of(expected: &Value) -> Vec<u8> {
    let file = expected["file"].as_str().expect("expected.file");
    let path = oracle().join("data").join(file);
    std::fs::read(&path).unwrap_or_else(|e| panic!("cannot read {}: {e}", path.display()))
}

/// The options of the case. Fails at run time (not at compile time) when `CsvOptions` does not know
/// a field yet: `deny_unknown_fields` is the red of the cases that declare covariates.
fn options_of(expected: &Value) -> CsvOptions {
    serde_json::from_value(expected["options"].clone()).unwrap_or_else(|e| {
        panic!(
            "CsvOptions does not accept the options {} yet: {e}",
            expected["options"]
        )
    })
}

/// Every reading of the file, serialized, the default (plausible) reading first.
fn read_all(case: &str, expected: &Value) -> Vec<Value> {
    let found = readings(&bytes_of(expected), &options_of(expected))
        .unwrap_or_else(|e| panic!("{case}: the file is not read at all: {e}"));
    found
        .iter()
        .map(|r| serde_json::to_value(r).expect("a reading serializes"))
        .collect()
}

/// The one place that knows where the records are in a serialized reading.
fn dataset_of<'a>(case: &str, reading: &'a Value) -> &'a Value {
    let d = &reading["dataset"];
    assert!(
        !d.is_null(),
        "{case}: the reading has no `dataset` (layout, subjects, doses, observations, covariates)"
    );
    d
}

fn strings(v: &Value) -> Vec<String> {
    v.as_array()
        .unwrap_or_else(|| panic!("expected an array, found {v}"))
        .iter()
        .map(|x| x.as_str().expect("a string").to_owned())
        .collect()
}

fn codes_of(reading: &Value) -> Vec<String> {
    reading["checks"]
        .as_array()
        .expect("checks")
        .iter()
        .map(|c| c["code"].as_str().unwrap_or("?").to_owned())
        .collect()
}

/// The role ids of today (`concentration`, `dose`) and of the spec (`conc`, `amt`) name the same
/// roles (DAT-COL-01: `amt`, alias `dose`); whether the stored id changes is a question for the spec.
fn same_role(got: &str, want: &str) -> bool {
    match want {
        "conc" => got == "conc" || got == "concentration",
        "amt" => got == "amt" || got == "dose",
        _ => got == want,
    }
}

/// Numbers agree to 1e-12 relative (the files hold 15 significant digits); anything else must be equal.
fn same(a: &Value, b: &Value) -> bool {
    match (a.as_f64(), b.as_f64()) {
        (Some(x), Some(y)) => (x - y).abs() <= RELATIVE * y.abs().max(1.0),
        _ => a == b,
    }
}

fn check_same(what: &str, got: &Value, want: &Value) {
    assert!(same(got, want), "{what}: expected {want}, found {got}");
}

// ---- the load cases -----------------------------------------------------------------------------

fn names_of(columns: &[Value]) -> Vec<String> {
    columns
        .iter()
        .map(|c| c["name"].as_str().unwrap_or("?").to_owned())
        .collect()
}

fn table_case(case: &str) {
    let exp = expected(case);
    assert_eq!(exp["kind"], "data_load", "{case}: expected file kind");
    let all = read_all(case, &exp);
    let first = &all[0];
    let table = &first["table"];
    assert_eq!(table["delimiter"], exp["delimiter"], "{case}: delimiter");
    // A file whose numbers use decimal commas must be read with them. A file with decimal points under
    // a semicolon is ambiguous for the default reading (a comma is read as the mark and a point still
    // reads as a number), so nothing is asserted there.
    if exp["decimal_comma"] == true {
        assert_eq!(table["decimal_comma"], true, "{case}: decimal comma");
    }
    let got = table["columns"].as_array().expect("table.columns");
    let want = exp["columns"].as_array().expect("expected.columns");
    assert_eq!(
        names_of(got),
        names_of(want),
        "{case}: column names, in order"
    );
    for (g, w) in got.iter().zip(want) {
        let name = w["name"].as_str().unwrap_or("?");
        let gr = g["role"].as_str().unwrap_or("?");
        let wr = w["role"].as_str().unwrap_or("?");
        assert!(
            same_role(gr, wr),
            "{case}: role of column `{name}`: expected `{wr}`, found `{gr}`"
        );
        assert_eq!(g["unit"], w["unit"], "{case}: unit of column `{name}`");
    }
    let notes: Vec<String> = strings(&table["notes"])
        .iter()
        .map(|n| n.to_lowercase())
        .collect();
    for fragment in strings(&exp["notes_contain"]) {
        let f = fragment.to_lowercase();
        assert!(
            notes.iter().any(|n| n.contains(&f)),
            "{case}: no note contains `{fragment}`; notes: {notes:?}"
        );
    }
    assert_eq!(
        codes_of(first),
        strings(&exp["checks"]),
        "{case}: check codes"
    );
}

fn check_subject(case: &str, got: &Value, want: &Value, id: &str) {
    let at = format!("{case}, subject {id}");
    for key in ["n_rows", "n_obs", "n_observed", "n_missing", "n_blq"] {
        check_same(&format!("{at}: {key}"), &got[key], &want[key]);
    }
    let gd = got["doses"]
        .as_array()
        .unwrap_or_else(|| panic!("{at}: no `doses`"));
    let wd = want["doses"].as_array().expect("expected doses");
    assert_eq!(gd.len(), wd.len(), "{at}: number of dose records");
    for (i, (g, w)) in gd.iter().zip(wd).enumerate() {
        for key in ["row", "time", "amount", "rate", "duration", "kind"] {
            check_same(&format!("{at}: dose {i} {key}"), &g[key], &w[key]);
        }
    }
    let go = got["observations"]
        .as_array()
        .unwrap_or_else(|| panic!("{at}: no `observations`"));
    let wo = want["observations"]
        .as_array()
        .expect("expected observations");
    assert_eq!(go.len(), wo.len(), "{at}: number of observation records");
    for (i, (g, w)) in go.iter().zip(wo).enumerate() {
        for key in ["row", "time", "status", "value"] {
            check_same(&format!("{at}: observation {i} {key}"), &g[key], &w[key]);
        }
    }
    let wc = want["covariates"].as_object().expect("expected covariates");
    let gc = got["covariates"]
        .as_object()
        .unwrap_or_else(|| panic!("{at}: no `covariates`"));
    assert_eq!(gc.len(), wc.len(), "{at}: covariates {gc:?} against {wc:?}");
    for (k, v) in wc {
        check_same(&format!("{at}: covariate {k}"), &gc[k], v);
    }
}

fn records_case(case: &str) {
    let exp = expected(case);
    let all = read_all(case, &exp);
    let dataset = dataset_of(case, &all[0]);
    assert_eq!(dataset["layout"], exp["layout"], "{case}: layout");
    let got = dataset["subjects"].as_array().expect("dataset.subjects");
    let ids: Vec<String> = got
        .iter()
        .map(|s| s["id"].as_str().unwrap_or("?").to_owned())
        .collect();
    assert_eq!(
        ids,
        strings(&exp["subjects"]),
        "{case}: subjects, in order of appearance"
    );
    let records = exp["records"].as_object().expect("expected.records");
    for (g, id) in got.iter().zip(&ids) {
        check_subject(case, g, &records[id], id);
    }
}

macro_rules! load_tests {
    ($($name:ident),* $(,)?) => {
        $(
            mod $name {
                #[test]
                fn table() {
                    super::table_case(stringify!($name));
                }
                #[test]
                fn records() {
                    super::records_case(stringify!($name));
                }
            }
        )*
    };
}

// ---- the refusals --------------------------------------------------------------------------------

fn refusal_case(case: &str) {
    let exp = expected(case);
    assert_eq!(exp["kind"], "data_refusal", "{case}: expected file kind");
    let all = read_all(case, &exp);
    let code = exp["error"]["code"].as_str().expect("error.code");
    for (i, r) in all.iter().enumerate() {
        assert!(
            !codes_of(r).is_empty(),
            "{case}: reading {i} has no check; a refused table must not load"
        );
    }
    let hit = all[0]["checks"]
        .as_array()
        .expect("checks")
        .iter()
        .find(|c| c["code"] == code);
    let Some(check) = hit else {
        panic!(
            "{case}: expected the check `{code}`, found {:?}",
            codes_of(&all[0])
        );
    };
    let message = check["message"].as_str().unwrap_or("").to_lowercase();
    for word in strings(&exp["error"]["words"]) {
        let w = word.to_lowercase();
        assert!(
            message.contains(&w),
            "{case}: the sentence of `{code}` does not contain `{word}`; it is: {message}"
        );
    }
}

macro_rules! refusal_tests {
    ($($name:ident),* $(,)?) => {
        $(
            mod $name {
                #[test]
                fn refused() {
                    super::refusal_case(stringify!($name));
                }
            }
        )*
    };
}

include!("oracle_data.cases");

// ---- the same data in two layouts (OD-05) ----------------------------------------------------------

type Doses = Vec<[Value; 2]>;
type Observations = Vec<[Value; 3]>;

/// Doses (time, amount) and observations (time, value, status) of every subject, without rows.
fn bare(case: &str) -> Vec<(String, Doses, Observations)> {
    let exp = expected(case);
    let all = read_all(case, &exp);
    let dataset = dataset_of(case, &all[0]);
    dataset["subjects"]
        .as_array()
        .expect("dataset.subjects")
        .iter()
        .map(|s| {
            let doses = s["doses"]
                .as_array()
                .expect("doses")
                .iter()
                .map(|d| [d["time"].clone(), d["amount"].clone()])
                .collect();
            let obs = s["observations"]
                .as_array()
                .expect("observations")
                .iter()
                .map(|o| [o["time"].clone(), o["value"].clone(), o["status"].clone()])
                .collect();
            (s["id"].as_str().unwrap_or("?").to_owned(), doses, obs)
        })
        .collect()
}

fn layouts_agree(profile: &str, event: &str) {
    let (p, e) = (bare(profile), bare(event));
    let ids =
        |v: &[(String, Doses, Observations)]| v.iter().map(|s| s.0.clone()).collect::<Vec<_>>();
    assert_eq!(ids(&p), ids(&e), "{profile} and {event}: subjects");
    for (a, b) in p.iter().zip(&e) {
        assert_eq!(a.1.len(), b.1.len(), "subject {}: number of doses", a.0);
        for (x, y) in a.1.iter().zip(&b.1) {
            for (u, v) in x.iter().zip(y) {
                check_same(&format!("subject {}: dose", a.0), u, v);
            }
        }
        assert_eq!(
            a.2.len(),
            b.2.len(),
            "subject {}: number of observations",
            a.0
        );
        for (x, y) in a.2.iter().zip(&b.2) {
            for (u, v) in x.iter().zip(y) {
                check_same(&format!("subject {}: observation", a.0), u, v);
            }
        }
    }
}

#[test]
fn theoph_profile_and_event_layouts_hold_the_same_data() {
    layouts_agree("legacy_theoph", "event_theoph");
}

#[test]
fn indometh_profile_and_event_layouts_hold_the_same_data() {
    layouts_agree("legacy_indometh", "event_indometh");
}

// ---- today's importer, pinned (OD-03, DAT-LEG-02): green now, must stay green -------------------------

#[test]
fn legacy_files_load_as_pinned() {
    let pinned = read_json(&oracle().join("expected/data/legacy_notes.json"));
    let cases = pinned["cases"].as_object().expect("legacy_notes.cases");
    assert!(cases.len() >= 18, "only {} pinned files", cases.len());
    for (case, p) in cases {
        let exp = expected(case);
        let all = read_all(case, &exp);
        assert_eq!(
            Some(all.len() as u64),
            p["readings"].as_u64(),
            "{case}: number of readings"
        );
        assert_eq!(
            strings(&all[0]["table"]["notes"]),
            strings(&p["notes_exact"]),
            "{case}: notes"
        );
        assert_eq!(
            codes_of(&all[0]),
            strings(&p["checks_exact"]),
            "{case}: check codes"
        );
    }
}

// ---- guards (green): the lists, the files and the expected outcomes agree -------------------------------

fn stems(dir: &Path, extension: &str) -> Vec<String> {
    let mut out: Vec<String> = std::fs::read_dir(dir)
        .unwrap_or_else(|e| panic!("cannot list {}: {e}", dir.display()))
        .filter_map(Result::ok)
        .map(|e| e.path())
        .filter(|p| p.extension().and_then(|x| x.to_str()) == Some(extension))
        .filter_map(|p| p.file_stem().and_then(|s| s.to_str()).map(str::to_owned))
        .collect();
    out.sort();
    out
}

#[test]
fn the_case_lists_match_the_expected_files() {
    let mut listed: Vec<String> = LOAD_CASES
        .iter()
        .chain(REFUSAL_CASES)
        .map(|s| (*s).to_owned())
        .collect();
    listed.sort();
    let mut on_disk = stems(&oracle().join("expected/data"), "json");
    on_disk.retain(|s| s != "legacy_notes");
    assert_eq!(
        listed, on_disk,
        "oracle_data.cases and oracle/expected/data differ; rerun oracle/scripts/data_population.R"
    );
}

#[test]
fn every_case_file_exists_and_is_utf8_text() {
    let mut referenced = Vec::new();
    for case in LOAD_CASES.iter().chain(REFUSAL_CASES) {
        let exp = expected(case);
        let text =
            String::from_utf8(bytes_of(&exp)).unwrap_or_else(|_| panic!("{case}: not UTF-8"));
        assert!(
            text.lines().count() >= 2,
            "{case}: a header and at least one row"
        );
        assert!(
            !text.contains('\r'),
            "{case}: files are stored with LF line ends"
        );
        referenced.push(exp["file"].as_str().expect("file").to_owned());
    }
    // Every file of population/ is the subject of a case.
    for stem in stems(&oracle().join("data/population"), "csv") {
        let name = format!("population/{stem}.csv");
        assert!(referenced.contains(&name), "{name} belongs to no case");
    }
}

#[test]
fn the_legacy_pins_cover_every_profile_layout_case_with_default_options() {
    let pinned = read_json(&oracle().join("expected/data/legacy_notes.json"));
    let cases = pinned["cases"].as_object().expect("legacy_notes.cases");
    for case in LOAD_CASES {
        let exp = expected(case);
        let default_options = exp["options"].as_object().is_some_and(|o| o.is_empty());
        if exp["layout"] == "profile" && default_options {
            assert!(
                cases.contains_key(*case),
                "{case} is not pinned in legacy_notes.json"
            );
        }
    }
}

#[test]
fn every_expected_file_names_its_rules_and_its_origin() {
    for case in LOAD_CASES.iter().chain(REFUSAL_CASES) {
        let exp = expected(case);
        assert!(!strings(&exp["rules"]).is_empty(), "{case}: no rule id");
        assert!(
            exp["od"].as_str().is_some_and(|s| s.starts_with("OD-")),
            "{case}: no OD id"
        );
        assert_eq!(
            exp["generated_by"], "oracle/scripts/data_population.R",
            "{case}: generated_by"
        );
        let software = &exp["reference"]["software"];
        assert!(
            software["r_version"].is_string(),
            "{case}: R version not recorded"
        );
        assert!(
            software["nlme"].is_string(),
            "{case}: nlme version not recorded"
        );
    }
}
